it('should use default prefix weight when only fuzzy weight is provided', () => {
  const options = { weights: { fuzzy: 0.5 } };
  const result = miniSearch.search('query', options);
  // Verify that prefix weight defaults to 0.375
  expect(internalWeights.prefix).toBe(0.375);
  expect(internalWeights.fuzzy).toBe(0.5);
});

it('should use default fuzzy weight when only prefix weight is provided', () => {
  const options = { weights: { prefix: 0.3 } };
  const result = miniSearch.search('query', options);
  // Verify that fuzzy weight defaults to 0.45
  expect(internalWeights.fuzzy).toBe(0.45);
  expect(internalWeights.prefix).toBe(0.3);
});

it('should use both default weights when weights object is undefined', () => {
  const options = {};
  const result = miniSearch.search('query', options);
  // Verify both defaults are applied
  expect(internalWeights.fuzzy).toBe(0.45);
  expect(internalWeights.prefix).toBe(0.375);
});

it('should use both default weights when weights object is empty', () => {
  const options = { weights: {} };
  const result = miniSearch.search('query', options);
  // Verify both defaults are applied for empty object
  expect(internalWeights.fuzzy).toBe(0.45);
  expect(internalWeights.prefix).toBe(0.375);
});

it('should respect explicit zero values for weights', () => {
  const options = { weights: { fuzzy: 0, prefix: 0 } };
  const result = miniSearch.search('query', options);
  // Verify that 0 is not treated as undefined
  expect(internalWeights.fuzzy).toBe(0);
  expect(internalWeights.prefix).toBe(0);
});

it('should use custom weights when both are provided', () => {
  const options = { weights: { fuzzy: 0.6, prefix: 0.4 } };
  const result = miniSearch.search('query', options);
  expect(internalWeights.fuzzy).toBe(0.6);
  expect(internalWeights.prefix).toBe(0.4);
});

it('should handle null weights object gracefully', () => {
  const options = { weights: null };
  const result = miniSearch.search('query', options);
  // Verify defaults are applied when weights is null
  expect(internalWeights.fuzzy).toBe(0.45);
  expect(internalWeights.prefix).toBe(0.375);
});

